// Limit to 10 jobs to preserve Apollo.io free credits (50/month)
const allJobs = $input.all();

// Filter out jobs that already have contacts
const jobsNeedingContacts = allJobs.filter(job => {
  const data = job.json;
  // Check if we already searched for contacts (to avoid re-processing)
  const notes = data.notes || data['Notes'] || '';
  return !notes.includes('Contact search completed');
});

// Limit to first 10
const limitedJobs = jobsNeedingContacts.slice(0, 10);

return limitedJobs;
